messages = [
    {"role": "system", "content": "You are a helpful assistant."},
    {"role": "user", "content": prompt}
]

combined_results = []

while True:
    response = client.chat.completions.create(
        model="gpt-4o",
        tools=tools,
        messages=messages
    )

    message = response.choices[0].message
    messages.append(message)

    if not message.tool_calls:
        break

    for tool_call in message.tool_calls:
        slug = tool_call.function.name
        args = json.loads(tool_call.function.arguments)
        print(f"Executing tool: {slug}")

        try:
            if slug.startswith("COMPOSIO_"):
                # Meta-tools must be executed via execute_meta
                result = session._client.tool_router.session.execute_meta(
                    session_id=session.session_id,
                    slug=slug,
                    arguments=args
                )
            else:
                result = session.execute(
                    tool_slug=slug,
                    arguments=args
                )

            result_data = result.data if hasattr(result, "data") else result

            # Store the result of COMPOSIO_MULTI_EXECUTE_TOOL specifically if that's what we want
            if slug == "COMPOSIO_MULTI_EXECUTE_TOOL":
                combined_results.append(result_data)

            messages.append({
                "role": "tool",
                "tool_call_id": tool_call.id,
                "content": json.dumps(result_data)
            })
        except Exception as e:
            print(f"Error executing {slug}: {e}")
            messages.append({
                "role": "tool",
                "tool_call_id": tool_call.id,
                "content": json.dumps({"error": str(e)})
            })

# Save the combined JSON output to result.json
output_path = "/home/user/multi-execute-task/result.json"
# The requirement says "Save the combined JSON output of these executions"
# Usually this means the result of the multi-execute tool.
with open(output_path, "w") as f:
    json.dump(combined_results, f, indent=4)

